algorithms.pseudocode:
Algorithm  PATH-SPACE-LAWS(F, G, H, s, u, t)
  Require: filtrations F, G, H on a finite simplex set S; 0 <= s <= u <= t <= 1
  // --- isometry: interleaving distance = sup of weight gaps ---
  function DIST(A, B):
      return max over sigma in S of |A.weight(sigma) - B.weight(sigma)|
  // --- geodesic interpolation ---
  function LERP(A, B, r):
      return filtration with weight(sigma) = (1-r)*A.weight(sigma) + r*B.weight(sigma)
  // --- 1. constant-speed identity ---
  assert DIST(LERP(F,G,s), LERP(F,G,t)) == |s - t| * DIST(F, G)
  // --- 2. reparametrisation closure ---
  for a, b in [0,1]^2:
      assert LERP(LERP(F,G,a), LERP(F,G,b), t) == LERP(F, G, (1-t)*a + t*b)
  // --- 3. geodesic-segment (betweenness) law ---
  assert DIST(LERP(F,G,s),LERP(F,G,u)) + DIST(LERP(F,G,u),LERP(F,G,t))
         == DIST(LERP(F,G,s), LERP(F,G,t))
  // --- 4. Busemann convexity ---
  defect <- (1-t)*DIST(H,F) + t*DIST(H,G) - DIST(H, LERP(F,G,t))
  assert defect >= 0
  return defect
